import{z as o,x as s,o as e,c as d,q as t,j as i,D as a,d as B,s as r,S as n,b as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"代码数据的合成","description":"","frontmatter":{"title":"代码数据的合成","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/synthetic-code-pipeline.md","filePath":"llm/synthetic-code-pipeline.md","lastUpdated":1791413859000}'),C={name:"llm/synthetic-code-pipeline.md"};function p(D,E,F,h,m,c){const l=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=t('<h1 id="代码数据的合成" tabindex="-1">代码数据的合成 <a class="header-anchor" href="#代码数据的合成" aria-label="Permalink to &quot;代码数据的合成&quot;">​</a></h1><div class="epigraph"><p>代码把「对」从文本判断换成执行判断：编译与测试是最诚实的裁判，也是最容易被人钻空子的裁判。</p><footer>—— 据 Gunasekar 等 Textbooks Are All You Need；Wei 等 Magicoder 整理</footer></div><p><a href="/llm/synthetic-math-pipeline">上一课</a>的数学域用答案等价做真值，代码域把真值再往前推一步：不判输出对不对，直接跑。<a href="/llm/code-verifier-unittests">代码验证器</a>课立过沙箱与隐藏测例的规矩，<a href="/llm/textbook-synthetic">教科书式合成</a>讲过 phi-1 用合成教材补代码能力的路数。本课写题、解、测试三样都可合成时的完整生产线，以及执行反馈在放量的同时放进来什么新风险。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>代码合成的特殊性在于三样东西都能造：题目可以从开源片段反推（给一段真实代码让教师写出「这段代码回答的问题」），解法可以由教师生成，测试可以由教师补写。三样都能造意味着生产线可能自洽地空转：教师出的题配教师写的解配教师写的测试，全部通过，整体却是对教师分布的自食。工程事故集中在三处。测试太松：恒真断言放行一切实现。测试泄漏：测例进了题面，模型学会硬编码答案。环境漂移：依赖版本不钉死，同一段代码今天过明天不过，过滤器静默变成随机数。<span class="marginnote">常见误区：初学者容易把「测试通过」直接等同于「代码正确」。测试只是抽样检查——恒真断言、只测正常路径、测例泄漏进题面时，通过的解可能根本没实现题意。执行反馈把裁判换成了物理层，但裁判本身也要被质检。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>生产线四站。种子站：从许可干净的仓库取函数级片段作种子——这是有源改写，<a href="/llm/the-stack-v2">The Stack v2</a>的文件级许可检测是原料闸；纯无源出题的覆盖更飘，默认不做。出题站：教师围绕种子写题面与参考解，题面过「自包含」检查——不依赖隐藏上下文与未给定义。执行站：参考解与候选解都进沙箱，<a href="/llm/tool-sandbox">工具沙箱</a>的快照与资源预算照搬；测试合成物要先验「能杀掉坏实现」——用几组变异代码（改边界、删检查）验证测试的杀伤力，恒真测试直接淘汰。整形站：失败轨迹不是废料，修复对（错误版本加补丁）是更值钱的监督；冗余重试与循环步剪枝后入库。</p>',7)),(e(),i(n,null,{default:a(()=>[r(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEED%5B%22%E7%A7%8D%E5%AD%90%EF%BC%9A%E8%AE%B8%E5%8F%AF%E5%B9%B2%E5%87%80%E7%9A%84%E4%BB%A3%E7%A0%81%E7%89%87%E6%AE%B5%22%5D%20--%3E%20TOPIC%5B%22%E6%95%99%E5%B8%88%E5%87%BA%E9%A2%98%E9%9D%A2%E4%B8%8E%E5%8F%82%E8%80%83%E8%A7%A3%22%5D%0A%20%20TOPIC%20--%3E%20SELF%7B%22%E8%87%AA%E5%8C%85%E5%90%AB%E6%A3%80%E6%9F%A5%E9%80%9A%E8%BF%87%EF%BC%9F%22%7D%0A%20%20SELF%20--%3E%7C%E5%90%A6%7C%20DROP%5B%22%E4%B8%A2%E5%BC%83%22%5D%0A%20%20SELF%20--%3E%7C%E6%98%AF%7C%20TESTS%5B%22%E6%95%99%E5%B8%88%E8%A1%A5%E5%86%99%E5%8D%95%E5%85%83%E6%B5%8B%E8%AF%95%22%5D%0A%20%20TESTS%20--%3E%20KILL%7B%22%E5%8F%98%E5%BC%82%E6%B5%8B%E8%AF%95%EF%BC%9A%E8%83%BD%E6%9D%80%E5%9D%8F%E5%AE%9E%E7%8E%B0%EF%BC%9F%22%7D%0A%20%20KILL%20--%3E%7C%E6%81%92%E7%9C%9F%7C%20CUT%5B%22%E6%B7%98%E6%B1%B0%E6%B5%8B%E8%AF%95%E6%88%96%E6%95%B4%E9%A2%98%22%5D%0A%20%20KILL%20--%3E%7C%E6%9C%89%E6%95%88%7C%20RUN%5B%22%E6%B2%99%E7%AE%B1%E6%89%A7%E8%A1%8C%E5%80%99%E9%80%89%E8%A7%A3%22%5D%0A%20%20RUN%20--%3E%7C%E6%B5%8B%E8%AF%95%E9%80%9A%E8%BF%87%7C%20KEEP%5B%22%E5%85%A5%E5%BA%93%EF%BC%9A%E8%A7%A3%E4%B8%8E%E5%A4%B1%E8%B4%A5%E4%BF%AE%E5%A4%8D%E5%AF%B9%22%5D%0A%20%20RUN%20--%3E%7C%E5%A4%B1%E8%B4%A5%7C%20REPAIR%5B%22%E4%BF%AE%E5%A4%8D%E5%BE%AA%E7%8E%AF%EF%BC%8C%E6%88%90%E5%AF%B9%E5%85%A5%E5%BA%93%E6%88%96%E4%B8%A2%E5%BC%83%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[B("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"执行反馈的价值在把拦截率从「裁判可信」升级到「物理层可信」：编译错误、运行超时、断言失败都是不可辩驳的信号，于是代码域可以承受比开放域高一个量级的采样量。但执行判的是「满足这组测试」，不是「满足题意」——测试与题意之间的缝隙就是投机取巧的入口，测例泄漏只是缝隙中最粗的一条。变异测试堵的是测试质量这一环：让测试先证明自己能区分好坏实现，才配当裁判。自食风险的机制防线比数学域更依赖原料——数学还有教材与竞赛题当外部题源，代码的种子只能来自真实仓库，真实种子的占比是这条生产线免于空转的压舱石；教科书式合成之所以有效，是因为它把真实种子与教师生成的「教材化解释」按结构配比，而不是让教师从头写整个世界。",-1)),(e(),i(n,null,{default:a(()=>[r(l,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E6%95%99%E5%B8%88%E5%86%99%E7%9A%84%E6%B5%8B%E8%AF%95%E5%A5%97%E4%BB%B6%22%5D%20--%3E%20M%5B%22%E7%94%9F%E6%88%90%E5%8F%98%E5%BC%82%E4%BD%93%3A%20%E6%94%B9%E8%BE%B9%E7%95%8C%2F%E5%88%A0%E6%A3%80%E6%9F%A5%2F%E6%8D%A2%E8%BF%90%E7%AE%97%E7%AC%A6%22%5D%0A%20%20M%20--%3E%20E%5B%22%E5%8F%98%E5%BC%82%E4%BD%93%E9%80%90%E4%B8%AA%E8%BF%9B%E6%B2%99%E7%AE%B1%E8%B7%91%E6%B5%8B%E8%AF%95%22%5D%0A%20%20E%20--%3E%20K%7B%22%E6%B5%8B%E8%AF%95%E8%83%BD%E5%8F%91%E7%8E%B0%E8%BF%99%E4%B8%AA%E5%8F%98%E5%BC%82%3F%22%7D%0A%20%20K%20--%3E%7C%E6%9D%80%E5%BE%97%E6%AD%BB%7C%20OK%5B%22%E8%AE%A1%E5%85%A5%E6%9D%80%E4%BC%A4%E6%95%B0%22%5D%0A%20%20K%20--%3E%7C%E6%9D%80%E4%B8%8D%E6%AD%BB%7C%20SURV%5B%22%E5%8F%98%E5%BC%82%E4%BD%93%E5%AD%98%E6%B4%BB%3A%20%E6%B5%8B%E8%AF%95%E5%A4%AA%E6%9D%BE%22%5D%0A%20%20SURV%20--%3E%20C%5B%22%E6%B7%98%E6%B1%B0%E6%88%96%E9%87%8D%E5%86%99%E8%AF%A5%E6%B5%8B%E8%AF%95%22%5D%0A%20%20OK%20--%3E%20Q%5B%22%E6%9D%80%E4%BC%A4%E7%8E%87%E8%BE%BE%E6%A0%87%2C%20%E6%B5%8B%E8%AF%95%E6%89%8D%E6%9C%89%E8%B5%84%E6%A0%BC%E5%BD%93%E8%A3%81%E5%88%A4%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">数字实例：对参考解生成 10 个变异体（把 \\(\\lt\\) 改成 \\(\\le\\)、删掉空指针检查之类），测试套件杀掉 9 个、放过 1 个，杀伤率 90%。工程上常设门槛（如 80%），低于门槛的测试套件不许参与数据过滤。</span></p><p><span class="marginnote">phi-1 的 1.3B 模型在 HumanEval 上过半，公开归因给「教科书级」合成数据——但其配方里真实仓库种子与执行过滤都在。把结论读成「纯合成即可」，会漏掉这条管线最贵的两个部件。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>执行验证只覆盖可执行代码：前端视觉、数据科学脚本、基础设施配置的「对」很难用断言钉死，这些域的过滤器退回裁判打分档，拦截率随之退化。测试杀伤力检查增加成本，且只保证测过的变异类，测不出「题意与测试同时偏」的情形。环境钉版本是运维纪律不是技术难题，失守的代价是过滤器静默变成噪声源——这类失败在日志里表现为通过率的日间漂移。最后，代码合成与工具调用共享沙箱基建但目标不同：前者造训练数据，后者造智能体轨迹，轨迹的观测真实性与多步结构是下一课的主题。<span class="marginnote">直觉类比：真实种子之于合成管线，就像野生种群之于育种——全部用教师自产的数据配种，分布会越滚越窄（自食）；每个批次掺入真实代码片段，就是把「野外基因」不断引进来，防止整条线退化成对教师分布的复述。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三样都可合成：种子反推题面、教师写解、教师补测试；自洽空转是结构性风险。</li><li>测试先过变异测试证明杀伤力，恒真测试淘汰。</li><li>题面、测例、环境三隔离，防模型学会硬编码。</li><li>失败修复对是资产；执行拦截率撑起代码域的放量。</li><li>真实种子占比是免于自食的压舱石。</li><li>出处：Gunasekar 等 2023；Wei 等 Magicoder 2023；Chen 等 HumanEval 2021；BigCode 2024。</li></ul>',6))])}const T=o(C,[["render",p]]);export{f as __pageData,T as default};
